"""No third-party dependencies. Builds isolated codecs; never launches or modifies a game."""
import hashlib
import json
import os
from pathlib import Path
import queue
import struct
import subprocess
import threading
import uuid
import zlib

ROOT = Path(__file__).resolve().parents[1]
BUILD = ROOT / "artifacts" / "protocol"
VECTORS = BUILD / "vectors"
SESSION = uuid.UUID("00112233-4455-6677-8899-aabbccddeeff").bytes


def fixtures():
    VECTORS.mkdir(parents=True, exist_ok=True)
    # Independent Python struct oracle, not output generated by either codec under test.
    def wire(body):
        return struct.pack("<4sHHHHI16sQQQQ", b"MCDN", 0, 1, 3, 0, len(body), SESSION,
                           2**64-1, 2**63, 2**53+1, 0) + body

    def save(name, data):
        (VECTORS / name).write_bytes(data)

    small = wire('{"counter":"9007199254740993","label":"原生桥接"}'.encode())
    save("good-small.wire", small)
    save("good-empty.wire", wire(b""))
    save("good-max.wire", wire(b"a" * 2**20))
    for label, offset, fmt, value in [
        ("magic", 0, "I", 0), ("major", 4, "H", 1), ("minor", 6, "H", 2),
        ("type", 8, "H", 0), ("unknown-type", 8, "H", 23), ("flags", 10, "H", 1),
        ("length", 12, "I", 2**20+1), ("unsigned-length", 12, "I", 2**32-1),
    ]:
        bad = bytearray(small); struct.pack_into("<" + fmt, bad, offset, value)
        save("bad-" + label + ".wire", bad)
    save("bad-short-header.wire", small[:63])
    save("bad-short-body.wire", small[:-1])
    # Do not feed trailing garbage as a valid standalone stream: decoder.complete must reject it.
    save("bad-trailing.wire", small + b"!")

    pixels = bytes(range(16))
    frame = bytearray(256) + pixels
    struct.pack_into("<4sHHII16sQQQQQQIIIIIIII", frame, 0,
                     b"MCDF", 0, 1, 256, len(pixels), SESSION,
                     2**64-1, 2**63, 7, 2**64-1, 2**63+1, 2**53+1,
                     2, 2, 8, 1, 3, 0, 0, 0)
    struct.pack_into("<6d4f2d5QIIQQ", frame, 112,
                     12.5, -3.25, 0.125, 1.0, 0.0, -1.0,
                     90.0, -15.0, 0.5, 1.0, 1.8, 4.0,
                     100, 110, 120, 130, 10_000_000,  # five QPC values including frequency
                     # Remaining fields start at 232; use separate packing below.
                     0, 0, 0, 0)
    struct.pack_into("<IIQQ", frame, 232, 1, zlib.crc32(pixels), 9, 0)
    save("good-pose.frame", frame)
    for label, offset, fmt, value in [
        ("frame-magic", 0, "I", 0), ("frame-major", 4, "H", 1), ("frame-minor", 6, "H", 2),
        ("frame-header", 8, "I", 128), ("pixels", 12, "I", 15), ("width-zero", 80, "I", 0),
        ("width-overflow", 80, "I", 2**32-1), ("height", 84, "I", 1025), ("stride", 88, "I", 9),
        ("format", 92, "I", 2), ("layers", 96, "I", 4), ("bottom-up", 100, "I", 2),
        ("alpha", 104, "I", 2), ("reserved", 108, "I", 1), ("nan", 112, "d", float("nan")),
        ("angle", 160, "f", float("inf")), ("pivot", 168, "f", 1.5),
        ("scale", 176, "d", 0), ("range", 184, "d", -1), ("clock", 224, "Q", 0),
        ("crc", 236, "I", 0), ("reserved-tail", 248, "Q", 1), ("corrupt-pixel", 256, "B", 255),
    ]:
        bad = bytearray(frame); struct.pack_into("<" + fmt, bad, offset, value)
        save("bad-" + label + ".frame", bad)
    save("bad-truncated.frame", frame[:-1])


def run(command, timeout=60):
    result = subprocess.run(list(map(str, command)), cwd=ROOT, text=True, encoding="utf-8",
                            errors="replace", capture_output=True, timeout=timeout)
    if result.returncode:
        raise RuntimeError(result.stdout + result.stderr)
    return (result.stdout + result.stderr).strip()


def main():
    fixtures()
    java_build = BUILD / "java"
    java_build.mkdir(parents=True, exist_ok=True)
    sources = sorted((ROOT / "src/java").rglob("*.java")) + sorted((ROOT / "tests/java").rglob("*.java"))
    env = {**os.environ, "DOTNET_CLI_TELEMETRY_OPTOUT": "1", "DOTNET_SKIP_FIRST_TIME_EXPERIENCE": "1",
           "DOTNET_CLI_HOME": str(BUILD / "dotnet-home"), "DOTNET_CLI_UI_LANGUAGE": "en",
           "APPDATA": str(BUILD / "appdata")}
    (BUILD / "appdata").mkdir(exist_ok=True)
    project = ROOT / "tests/dotnet/Mcdn.Protocol.Bench.csproj"
    restored = subprocess.run(["dotnet", "restore", str(project), "--configfile", str(ROOT / "NuGet.Config")],
                              cwd=ROOT, env=env, capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=60)
    if restored.returncode: raise RuntimeError(restored.stdout + restored.stderr)
    compiled = subprocess.run(["dotnet", "build", str(project), "-c", "Release", "--nologo", "--no-restore"],
                              cwd=ROOT, env=env, capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=60)
    if compiled.returncode: raise RuntimeError(compiled.stdout + compiled.stderr)
    run(["javac", "-encoding", "UTF-8", "-Xlint:all", "-Werror", "-d", java_build, *sources])
    dll = ROOT / "tests/dotnet/bin/Release/net10.0/Mcdn.Protocol.Bench.dll"
    java = ["java", "-cp", str(java_build), "dev.mcdn.protocol.Bench"]
    checks = [run(["dotnet", dll, "vectors", VECTORS]), run([*java, "vectors", VECTORS])]
    # Port selected by the OS. Read readiness with a bounded timeout and always reap our own child.
    server = subprocess.Popen(["dotnet", str(dll), "serve"], cwd=ROOT, stdout=subprocess.PIPE,
                              stderr=subprocess.PIPE, text=True)
    ready = queue.Queue()
    threading.Thread(target=lambda: ready.put(server.stdout.readline()), daemon=True).start()
    try:
        port = int(ready.get(timeout=10).strip())
        checks.append(run([*java, "connect", str(port)], timeout=25))
        stdout, stderr = server.communicate(timeout=10)
        if server.returncode: raise RuntimeError(stdout + stderr)
        checks.append(stdout.strip())
    finally:
        if server.poll() is None:
            server.kill(); server.communicate()
    hashes = {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest()
              for folder in (ROOT / "src", ROOT / "tests", ROOT / "tools")
              for p in sorted(folder.rglob("*"))
              if p.suffix in (".cs", ".java", ".py", ".csproj") and "obj" not in p.parts and "bin" not in p.parts}
    report = {"scope": "synthetic codec and loopback TCP; no game or shared-memory verification",
              "checks": checks, "vector_count": len(list(VECTORS.iterdir())), "source_sha256": hashes,
              "vector_sha256": {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(VECTORS.iterdir())}}
    (BUILD / "report.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    print("\n".join(checks))
    print("REPORT", BUILD / "report.json")


if __name__ == "__main__":
    main()
